    internal static int RowOffset(int scale)
    {
        return scale switch
        {
            2 => 0,
            3 => 4,
            4 => 13,
            _ => throw new ArgumentOutOfRangeException(
                nameof(scale),
                scale,
                "The HQx scale must be 2, 3, or 4."),
        };
    }
